const b = $('Audit form webhook').first().json.body || {}
const clean = s => String(s == null ? '' : s).replace(/[\u0000-\u001f\u007f<>]/g, '').trim()
const errors = []
const email = clean(b.email).toLowerCase()
if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('invalid_email')
const name = clean(b.name).slice(0, 100)
if (name.length < 2) errors.push('missing_name')
const website = clean(b.website).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '').slice(0, 200)
if (!/^[^\s.\/]+(\.[^\s.\/]+)+(\/\S*)?$/.test(website)) errors.push('invalid_website')
const svc = (Array.isArray(b.services) ? b.services : []).map(s => clean(s).toLowerCase())
const hasW = svc.includes('website'), hasE = svc.includes('emails')
if (!hasW && !hasE) errors.push('unknown_interest')
const budgets = ['under-1000', '1000-2500', '2500-plus']
const networking = b.source === 'networking' && b.consent_version === 'networking-consent-v1'
if (b.consent_version && !networking) errors.push('invalid_consent_profile')
const digits = clean(b.phone).replace(/\D/g, '')
let phone = clean(b.phone).slice(0,30)
if (networking) {
  if (!/^[+\d\s().-]+$/.test(phone) || !(/^[2-9]\d{2}[2-9]\d{6}$/.test(digits) || /^1[2-9]\d{2}[2-9]\d{6}$/.test(digits))) errors.push('invalid_phone')
  else phone = '+' + (digits.length === 10 ? '1' : '') + digits
  for (const key of ['email_marketing_consent','sms_marketing_consent']) if(typeof b[key] !== 'boolean') errors.push('invalid_' + key)
}
const recorded = new Date().toISOString()
const consent = networking ? {
  consent_profile:'networking-consent-v1', email_marketing_consent:b.email_marketing_consent===true?'TRUE':'FALSE',
  sms_marketing_consent:b.sms_marketing_consent===true?'TRUE':'FALSE',
  email_consent_at:b.email_marketing_consent===true?recorded:'', sms_consent_at:b.sms_marketing_consent===true?recorded:'',
  consent_recorded_at:recorded,consent_source:'https://boxxautomations.space/audit',consent_version:'networking-consent-v1'
} : {}
const lead = { ...consent,
  email, name, first_name: name.split(' ')[0], website,
  phone,
  interest: hasW && hasE ? 'both' : hasE ? 'emails' : 'website',
  nurture_path: hasW && hasE ? 'BOTH' : hasE ? 'EMAIL' : 'WEBSITE',
  budget: budgets.includes(clean(b.budget)) ? clean(b.budget) : '',
  source: clean(b.source).slice(0, 300),
}
return [{ json: { ok: errors.length === 0, errors, lead, raw: JSON.stringify(b).slice(0, 1500) } }]

const v = $input.first().json
return [{ json: { error_id: 'err_' + Date.now().toString(36), timestamp: new Date().toISOString(),
  workflow: 'BOXX - Lead Intake', email: v.lead.email, error_message: 'invalid_submission: ' + v.errors.join(','), payload: v.raw } }]

const cfg = $('Config').first().json
const v = $('Validate & normalize').first().json
const L = v.lead
const rows = $input.all().map(i => i.json).filter(r => r && r.email)
const ex = rows.find(r => String(r.email).toLowerCase().trim() === L.email)
const T = x => String(x == null ? '' : x).toUpperCase() === 'TRUE'
const now = new Date(), iso = now.toISOString()
const contact = { email: L.email, name: L.name, phone: L.phone, website: L.website, updated_at: iso, last_submission_at: iso }
const fresh = { interest: L.interest, budget: L.budget, source: L.source, nurture_path: L.nurture_path,
  nurture_status: 'ACTIVE', current_email: 0, framework_delivered: 'FALSE', next_email_due_at: '', stop_reason: '' }
let row, sendEmail1 = false, reason, isNew = false
if (!ex) {
  isNew = true; sendEmail1 = true; reason = 'new_lead'
  row = Object.assign({ lead_id: 'ld_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7), created_at: iso,
    calendly_booked: 'FALSE', unsubscribe_status: 'FALSE', client_status: 'PROSPECT', loom_status: 'PENDING' }, contact, fresh)
} else {
  const blocked = T(ex.unsubscribe_status) || T(ex.calendly_booked) || String(ex.client_status || '').toUpperCase() === 'ACTIVE'
  const start = new Date(ex.framework_delivered_at || ex.created_at)
  const ageDays = isNaN(start) ? 0 : (now - start) / 864e5
  if (!blocked && ageDays > cfg.resendAfterDays) {
    sendEmail1 = true; reason = 'resend_after_' + cfg.resendAfterDays + '_days'; row = Object.assign({}, contact, fresh)
  } else {
    reason = blocked ? 'existing_lead_blocked' : 'duplicate_within_window'; row = contact
  }
}
const profile = L.consent_profile === 'networking-consent-v1' || (ex && ex.consent_profile === 'networking-consent-v1')
const consent = L.consent_profile === 'networking-consent-v1' ? Object.fromEntries(["consent_profile","email_marketing_consent","sms_marketing_consent","email_consent_at","sms_consent_at","consent_recorded_at","consent_source","consent_version"].map(k=>[k,L[k]])) : (profile ? Object.fromEntries(["consent_profile","email_marketing_consent","sms_marketing_consent","email_consent_at","sms_consent_at","consent_recorded_at","consent_source","consent_version"].map(k=>[k,ex[k]])) : {})
if (profile) {
  Object.assign(row, consent)
  if(L.consent_profile === 'networking-consent-v1') row.source='networking'
  if (ex && T(ex.framework_delivered) && !sendEmail1 && !T(consent.email_marketing_consent) && !T(ex.unsubscribe_status) && !T(ex.calendly_booked) && String(ex.client_status).toUpperCase()!=='ACTIVE') {
    row.nurture_status='STOPPED'; row.stop_reason='no_email_marketing_consent'; row.next_email_due_at=''
  }
  if (ex && ex.stop_reason==='no_email_marketing_consent' && T(consent.email_marketing_consent) && !T(ex.unsubscribe_status) && !T(ex.calendly_booked) && String(ex.client_status).toUpperCase()!=='ACTIVE') { row.nurture_status='ACTIVE';row.stop_reason='' }
}
const sendSms = L.consent_profile==='networking-consent-v1' && T(L.sms_marketing_consent) && !(ex && T(ex.sms_opt_out)) && !(ex && ['PENDING','QUEUED','SENT','DELIVERED'].includes(String(ex.sms_confirmation_status).toUpperCase()))
if(sendSms) row.sms_confirmation_status='PENDING'
const lead = Object.assign({}, L, consent, { lead_id: ex ? ex.lead_id : row.lead_id })
return [{ json: { sendEmail1, sendSms, reason, isNew, row, lead } }]

const cfg = $('Config').first().json
const d = $('Decide').first().json, L = d.lead
const lines = ['Name: ' + L.name, 'Email: ' + L.email, 'Phone: ' + (L.phone || '-'), 'Website: ' + L.website,
  'Interest: ' + L.interest + ' (path ' + L.nurture_path + ')', 'Budget: ' + (L.budget || '-'), 'Source: ' + (L.source || '-'), '', 'System action: ' + d.reason]
const subject = (d.isNew ? 'New audit request: ' : 'Repeat audit request: ') + L.name + ' (' + L.website + ')'
return [{ json: { sgBody: {
  personalizations: [{ to: [{ email: cfg.notifyEmail }], subject }],
  from: { email: cfg.fromEmail, name: 'BOXX system' },
  content: [{ type: 'text/plain', value: lines.join('\n') }],
}, meta: { email: L.email } } }]

const result = (()=>{const rnd = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
const baseData = cfg => ({ site_url: cfg.siteUrl, calendly_url: cfg.calendlyUrl, framework_url: cfg.frameworkUrl, mailing_address: cfg.mailingAddress })
const cfg = $('Config').first().json
const L = $('Decide').first().json.lead
return [{ json: { sgBody: {
  personalizations: [{ to: [{ email: L.email }], subject: cfg.subjects[0],
    dynamic_template_data: Object.assign(baseData(cfg), { first_name: L.first_name, website: L.website, subject: cfg.subjects[0] }) }],
  from: { email: cfg.fromEmail, name: cfg.fromName }, reply_to: { email: cfg.replyTo },
  template_id: cfg.templates[L.nurture_path][0],
  asm: { group_id: cfg.asmGroupId },
  categories: ['boxx-nurture', 'email-1'], custom_args: { lead_id: L.lead_id, email_type: 'nurture-1' },
}, meta: { lead_id: L.lead_id, email: L.email, email_type: 'nurture-1' } } }]
})()
const leads=[$('Decide').first().json.lead]
for(let i=0;i<result.length;i++) {
 const L=leads[i]
 const first=true
 if(first && L.consent_profile==='networking-consent-v1' && String(L.email_marketing_consent).toUpperCase()!=='TRUE') {
  result[i].json.meta.auditOnly=true
  const body=result[i].json.sgBody
  delete body.template_id
  for(const p of body.personalizations) delete p.dynamic_template_data
  body.content=[{type:'text/plain',value:'Hi '+(L.first_name||String(L.name||'').split(' ')[0])+', thanks for requesting your free audit.\n\nDownload your free BOXX Website Conversion Framework: '+$('Config').first().json.frameworkUrl+'\n\nKaleel will review your website and email your audit recommendations. You have not signed up for promotional follow-up emails.\n\nBOXX Automations\n'+$('Config').first().json.mailingAddress+'\nhello@boxxautomations.space'}]
 }
}
return result

